type forthVM struct {
	stack []int
	defs  map[string][]string
}

// Forth evaluates a sequence of Forth source lines and returns the
// resulting stack (bottom to top), or an error.
func Forth(input []string) ([]int, error) {
	vm := &forthVM{
		stack: []int{},
		defs:  make(map[string][]string),
	}
	for _, line := range input {
		if err := vm.eval(strings.Fields(line)); err != nil {
			return nil, err
		}
	}
	return vm.stack, nil
}

func (vm *forthVM) eval(tokens []string) error {
	for i := 0; i < len(tokens); i++ {
		tok := tokens[i]
		if isNumber(tok) {
			n, _ := strconv.Atoi(tok)
			vm.stack = append(vm.stack, n)
			continue
		}
		name := strings.ToLower(tok)
		if name == ":" {
			if err := vm.define(tokens[i+1:]); err != nil {
				return err
			}
			// Skip past the definition; define() reports how far it consumed.
			i = i + 1 + vm.defLen(tokens[i+1:])
			continue
		}
		if body, ok := vm.defs[name]; ok {
			if err := vm.eval(body); err != nil {
				return err
			}
			continue
		}
		if err := vm.builtin(name); err != nil {
			return err
		}
	}
	return nil
}

// define parses a definition of the form `name ... ;` from tokens
// (tokens[0] is the word name) and stores its body.
func (vm *forthVM) define(tokens []string) error {
	if len(tokens) == 0 {
		return errForth
	}
	name := strings.ToLower(tokens[0])
	if isNumber(tokens[0]) {
		return errForth // cannot redefine a number
	}
	for i := 1; i < len(tokens); i++ {
		if strings.ToLower(tokens[i]) == ";" {
			vm.defs[name] = tokens[1:i]
			return nil
		}
	}
	return errForth // missing ;
}

// defLen returns how many tokens a definition starting at tokens[0]
// consumes, including the terminating `;`.
func (vm *forthVM) defLen(tokens []string) int {
	for i := 1; i < len(tokens); i++ {
		if strings.ToLower(tokens[i]) == ";" {
			return i + 1
		}
	}
	return len(tokens)
}

func (vm *forthVM) builtin(name string) error {
	switch name {
	case "+", "-", "*", "/":
		if len(vm.stack) < 2 {
			return errForth
		}
		top, second := vm.pop()
		switch name {
		case "+":
			vm.stack = append(vm.stack, second+top)
		case "-":
			vm.stack = append(vm.stack, second-top)
		case "*":
			vm.stack = append(vm.stack, second*top)
		default: // "/"
			if top == 0 {
				return errForth
			}
			vm.stack = append(vm.stack, second/top)
		}
	case "dup":
		if len(vm.stack) < 1 {
			return errForth
		}
		vm.stack = append(vm.stack, vm.stack[len(vm.stack)-1])
	case "drop":
		if len(vm.stack) < 1 {
			return errForth
		}
		vm.stack = vm.stack[:len(vm.stack)-1]
	case "swap":
		if len(vm.stack) < 2 {
			return errForth
		}
		vm.stack[len(vm.stack)-1], vm.stack[len(vm.stack)-2] =
			vm.stack[len(vm.stack)-2], vm.stack[len(vm.stack)-1]
	case "over":
		if len(vm.stack) < 2 {
			return errForth
		}
		vm.stack = append(vm.stack, vm.stack[len(vm.stack)-2])
	default:
		return errForth // undefined word
	}
	return nil
}

func (vm *forthVM) pop() (int, int) {
	top := vm.stack[len(vm.stack)-1]
	second := vm.stack[len(vm.stack)-2]
	vm.stack = vm.stack[:len(vm.stack)-2]
	return top, second
}

// isNumber reports whether tok is a number: an optional '-' followed
// by one or more ASCII digits.
func isNumber(tok string) bool {
	if tok == "" {
		return false
	}
	start := 0
	if tok[0] == '-' {
		if len(tok) == 1 {
			return false
		}
		start = 1
	}
	for _, c := range tok[start:] {
		if c < '0' || c > '9' {
			return false
		}
	}
	return true
}

