		if strings.ToLower(tokens[i]) == ";" {
			return i + 1
		}
	}
	return len(tokens)
}

func (vm *forthVM) builtin(name string) error {
	switch name {
	case "+", "-", "*", "/":
		if len(vm.stack) < 2 {
			return errForth
		}
		top, second := vm.pop()
		switch name {
		case "+":
			vm.stack = append(vm.stack, second+top)
		case "-":
			vm.stack = append(vm.stack, second-top)
		case "*":
			vm.stack = append(vm.stack, second*top)
		default: // "/"
			if top == 0 {
				return errForth
			}
			vm.stack = append(vm.stack, second/top)
		}
	case "dup":
		if len(vm.stack) < 1 {
			return errForth
		}
		vm.stack = append(vm.stack, vm.stack[len(vm.stack)-1])
	case "drop":
		if len(vm.stack) < 1 {
			return errForth
		}
		vm.stack = vm.stack[:len(vm.stack)-1]
	case "swap":
		if len(vm.stack) < 2 {
			return errForth
		}
		vm.stack[len(vm.stack)-1], vm.stack[len(vm.stack)-2] =
			vm.stack[len(vm.stack)-2], vm.stack[len(vm.stack)-1]
	case "over":
		if len(vm.stack) < 2 {
			return errForth
		}
		vm.stack = append(vm.stack, vm.stack[len(vm.stack)-2])
	default:
		return errForth // undefined word
	}
	return nil
}

func (vm *forthVM) pop() (int, int) {
	top := vm.stack[len(vm.stack)-1]
	second := vm.stack[len(vm.stack)-2]
	vm.stack = vm.stack[:len(vm.stack)-2]
	return top, second
}

// isNumber reports whether tok is a number: an optional '-' followed
// by one or more ASCII digits.
func isNumber(tok string) bool {
	if tok == "" {
		return false
	}
	start := 0
	if tok[0] == '-' {
		if len(tok) == 1 {
			return false
		}
		start = 1
	}
	for _, c := range tok[start:] {
		if c < '0' || c > '9' {
			return false
		}
	}
	return true
}
